input.new_string:
// A filament or printer preset named by a settings call, by the name Orca
// keys it by: one a person could pick, or one the project uses. A 3MF can
// select a system preset the person's list hides. Null for any other name.
inline const Preset* scope_preset(SettingsScope scope, const std::string& name)
{
    const PresetCollection& collection = scope_collection(scope);
    const Preset*           preset     = collection.find_preset(name, false);
    if (preset == nullptr || preset->is_default || preset->name != name)
        return nullptr;
    const std::vector<std::string>& project_filaments = wxGetApp().preset_bundle->filament_presets;
    const bool in_use = collection.get_selected_preset_name() == name ||
                        (scope == SettingsScope::Filament &&
                         std::find(project_filaments.begin(), project_filaments.end(), name) != project_filaments.end());
    return preset->is_visible || in_use ? preset : nullptr;
}

